import pathlib,json,hashlib,zipfile,datetime
ROOT=pathlib.Path(__file__).resolve().parents[1]
for d in ['configs','src','tests','outputs/logs','outputs/figures','outputs/checkpoints']:(ROOT/d).mkdir(parents=True,exist_ok=True)
with zipfile.ZipFile(ROOT/'official_worldts_source.zip') as archive:
 for entry in archive.infolist():
  assert (ROOT/entry.filename).resolve().is_relative_to(ROOT.resolve());archive.extract(entry,ROOT)
source=json.loads((ROOT/'configs/source_manifest.json').read_text(encoding='utf-8'))
for row in source:assert hashlib.sha256((ROOT/row['path']).read_bytes()).hexdigest()==row['sha256']
protocol={'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_commit':'269426ea6217d7152a244da0e209d922acd46d4f','repository_parent':'1ddba1c5b81f0045b5c9a884820ef44578e926f9','tasks':['NP','PJM'],'horizon':360,'seed':2021,'training_family':'same task-specific original Stage2 checkpoint; predictor-only; all other parameters and buffers frozen','forecast_objective':'MAE in train-standardized observation units, with original history RevIN undone by original decoder','optimizer':'Adam','learning_rate':1e-4,'batch_size':32,'max_steps':1000,'validation_frequency':50,'patience_validation_checks':5,'minimum_delta':0.,'selection':'official unweighted mean of validation batch MAEs; Step0 is eligible; full element-weighted MAE/MSE also saved','training_order':'PCG64 permutation seed2021; identical full batch sequence and Torch dropout RNG start for A0/A1/A2','smoke_steps':20,'lambda_rule':'one per task: median initial Predictor gradient-norm ratio full_latent/forecast_MAE across16 fixed training minibatches, model eval; no validation/test tuning','audit':'all official long-horizon validation origins, contiguous batch32; predictor-parameter gradients on8 fixed validation batches','horizon_segments':[[0,120],[120,240],[240,360]],'gradient_cosine_epsilon':1e-12,'zero_gradient_norm_threshold':1e-12,'near_zero_cosine_abs_threshold':.1,'time_block_lengths':[360,720,1680],'bootstrap_repetitions':2000,'bootstrap_seed':9281,'meaningful_validation_mae_gain':.01,'test_policy':'Phase0 original checkpoint verification only. No candidate test forecasts or test-based decisions. Validation-selected comparisons are feasibility evidence, not unbiased generalization estimates.','decision_policy':'Separate objective conflict, useful predictor intervention and novelty. A favorable A1/A2 only supports ordinary supervision; GO to a new mechanism requires a documented remaining pattern not explained by simple supervision. No gain or no actionable remaining mechanism is NO-GO for complex readout-aware loss.'}
p=ROOT/'configs/protocol.json'
if p.exists():assert {k:v for k,v in json.loads(p.read_text()).items() if k!='created_utc'}=={k:v for k,v in protocol.items() if k!='created_utc'}
else:p.write_text(json.dumps(protocol,indent=2),encoding='utf-8')
print('BOOTSTRAP_PINNED_SOURCE_PASS',len(source),flush=True)
